import RNA, random, multiprocessing as mp, time, sys
target = '..((((((((.......(.((((((....)))))).(((((((....))))))).).......))))))))..'

def f(s): return RNA.fold_compound(s).mfe()[0]
def dist(s): return RNA.bp_distance(f(s), target)

def worker(seed):
    r = random.Random(seed)
    best_d = 999; best = None
    for _ in range(300):
        start = ''.join(r.choice('ACGU') for _ in range(len(target)))
        seq, d = RNA.inverse_fold(start, target)
        if d == 0 and f(seq) == target:
            return ('SOLVED', seq)
        dd = dist(seq)
        if dd < best_d:
            best_d = dd; best = seq
    return (best_d, best)

if __name__ == '__main__':
    t = time.time()
    with mp.Pool(48) as p:
        results = list(p.imap_unordered(worker, range(384), chunksize=4))
    results.sort(key=lambda x: (x[0] != 'SOLVED', x[0] if x[0] != 'SOLVED' else 0))
    print('BEST:', results[0], 'time', time.time()-t, flush=True)
    # also count sols
    sols = [r for r in results if r[0] == 'SOLVED']
    print('n_sols', len(sols), flush=True)

